function longestOneWayRun(nums: number[]): number {
  let up = 1, down = 1, best = 1;
  for (let i = 1; i < nums.length; i++) {
    if (nums[i] > nums[i - 1]) { up++; down = 1; }
    else if (nums[i] < nums[i - 1]) { down++; up = 1; }
    else { up = 1; down = 1; }
    best = Math.max(best, up, down);
  }
  return best;
}

